const DEFAULT_IMAGE =
  'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=900&q=80';

const CATEGORY_IMAGES = {
  'fruits & vegetables':
    'https://images.unsplash.com/photo-1610832958506-aa56368176cf?auto=format&fit=crop&w=900&q=80',
  'dairy & eggs':
    'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=80',
  bakery:
    'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=900&q=80',
  beverages:
    'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80',
  snacks:
    'https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=900&q=80',
  'grains & pulses':
    'https://images.unsplash.com/photo-1506617420156-8e4536971650?auto=format&fit=crop&w=900&q=80',
  'meat & seafood':
    'https://images.unsplash.com/photo-1547592180-8d3e9a3b54f9?auto=format&fit=crop&w=900&q=80',
  'personal care':
    'https://images.unsplash.com/photo-1612817288484-6f916006741a?auto=format&fit=crop&w=900&q=80',
  household:
    'https://images.unsplash.com/photo-1581579185169-2aebc360c2c7?auto=format&fit=crop&w=900&q=80',
  'frozen foods':
    'https://images.unsplash.com/photo-1604909052743-94e8387a7c67?auto=format&fit=crop&w=900&q=80',
};

const PRODUCT_KEYWORDS = [
  { match: ['tomato', 'tomatoes'], src: 'https://images.unsplash.com/photo-1546470427-227c7f0d8c02?auto=format&fit=crop&w=900&q=80' },
  { match: ['onion', 'onions'], src: 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?auto=format&fit=crop&w=900&q=80' },
  { match: ['apple', 'apples'], src: 'https://images.unsplash.com/photo-1568702846914-96b305d2aaeb?auto=format&fit=crop&w=900&q=80' },
  { match: ['banana', 'bananas'], src: 'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?auto=format&fit=crop&w=900&q=80' },
  { match: ['milk'], src: 'https://images.unsplash.com/photo-1582719478185-2a6f5e0b8c05?auto=format&fit=crop&w=900&q=80' },
  { match: ['bread'], src: 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=900&q=80' },
  { match: ['rice'], src: 'https://images.unsplash.com/photo-1586201375761-83865001e31c?auto=format&fit=crop&w=900&q=80' },
  { match: ['chips', 'snack'], src: 'https://images.unsplash.com/photo-1566478989037-eec170784d0b?auto=format&fit=crop&w=900&q=80' },
  { match: ['toothpaste', 'soap'], src: 'https://images.unsplash.com/photo-1556228578-8a7a62be3a11?auto=format&fit=crop&w=900&q=80' },
];

const STAT_IMAGES = {
  revenue:
    'https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=900&q=80',
  chart:
    'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=80',
  stock:
    'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=900&q=80',
  store:
    'https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&w=900&q=80',
};

const normalize = (value) => String(value || '').trim().toLowerCase();

export function getCategoryImage(name) {
  const key = normalize(name);
  return CATEGORY_IMAGES[key] || DEFAULT_IMAGE;
}

export function getProductImage(product = {}) {
  const direct = String(product.image_url || '').trim();
  if (direct) return direct;

  const name = normalize(product.name || product.product_name);
  const category = normalize(product.category_name);

  const keywordMatch = PRODUCT_KEYWORDS.find(({ match }) =>
    match.some((term) => name.includes(term) || category.includes(term))
  );

  if (keywordMatch) return keywordMatch.src;
  if (CATEGORY_IMAGES[category]) return CATEGORY_IMAGES[category];

  return DEFAULT_IMAGE;
}

export function getStatImage(key) {
  return STAT_IMAGES[key] || DEFAULT_IMAGE;
}

export const DEFAULT_VISUAL_IMAGE = DEFAULT_IMAGE;
